// Grammar:
//   query    = or_expr
//   or_expr  = and_expr { "OR" and_expr }
//   and_expr = unary { ["AND"] unary }        (adjacency => implicit AND)
//   unary    = ["NOT"] primary
//   primary  = word | phrase | tag_term | "(" or_expr ")"
//
// Words/phrases match (case-insensitively) across title, url, description,
// note, AND tag names. #tag matches tag names only.

export class SearchError extends Error {}

// ---- Tokenizer ---------------------------------------------------------
function tokenize(input) {
  const tokens = [];
  let i = 0;
  const s = input;
  while (i < s.length) {
    const c = s[i];
    if (c === ' ' || c === '\t' || c === '\n') { i++; continue; }
    if (c === '(') { tokens.push({ type: 'LPAREN' }); i++; continue; }
    if (c === ')') { tokens.push({ type: 'RPAREN' }); i++; continue; }
    if (c === '"') {
      // Quoted phrase: literal text, operators inside are NOT operators.
      let j = i + 1;
      let val = '';
      let closed = false;
      while (j < s.length) {
        if (s[j] === '"') { closed = true; break; }
        val += s[j];
        j++;
      }
      if (!closed) throw new SearchError('Unbalanced quotes in query.');
      tokens.push({ type: 'PHRASE', value: val });
      i = j + 1;
      continue;
    }
    if (c === '#') {
      let j = i + 1;
      let val = '';
      while (j < s.length && !/[\s()"]/.test(s[j])) { val += s[j]; j++; }
      if (!val) throw new SearchError('Empty #tag term in query.');
      tokens.push({ type: 'TAG', value: val });
      i = j;
      continue;
    }
    // Bare run of non-space, non-paren, non-quote characters.
    let j = i;
    let val = '';
    while (j < s.length && !/[\s()"]/.test(s[j])) { val += s[j]; j++; }
    if (val === 'AND' || val === 'OR' || val === 'NOT') {
      tokens.push({ type: val });
    } else {
      tokens.push({ type: 'WORD', value: val });
    }
    i = j;
  }
  return tokens;
}

// ---- Parser (recursive descent) ---------------------------------------
function parse(tokens) {
  let pos = 0;
  const peek = () => tokens[pos];
  const next = () => tokens[pos++];

  function parseOr() {
    let left = parseAnd();
    while (peek() && peek().type === 'OR') {
      next();
      const right = parseAnd();
      left = { op: 'OR', left, right };
    }
    return left;
  }

  function parseAnd() {
    let left = parseUnary();
    while (peek() && isOperandStart(peek())) {
      // Explicit AND or adjacency (implicit AND).
      if (peek().type === 'AND') next();
      const right = parseUnary();
      left = { op: 'AND', left, right };
    }
    // A stray explicit AND with no following operand is an error.
    if (peek() && peek().type === 'AND') {
      throw new SearchError('Dangling operator in query.');
    }
    return left;
  }

  function isOperandStart(tok) {
    return tok.type === 'AND' || tok.type === 'NOT' ||
      tok.type === 'WORD' || tok.type === 'PHRASE' ||
      tok.type === 'TAG' || tok.type === 'LPAREN';
  }

  function parseUnary() {
    if (peek() && peek().type === 'NOT') {
      next();
      const operand = parseUnary();
      return { op: 'NOT', operand };
    }
    return parsePrimary();
  }

  function parsePrimary() {
    const tok = peek();
    if (!tok) throw new SearchError('Dangling operator in query.');
    if (tok.type === 'OR' || tok.type === 'AND' || tok.type === 'NOT') {
      throw new SearchError('Dangling operator in query.');
    }
    if (tok.type === 'LPAREN') {
      next();
      if (peek() && peek().type === 'RPAREN') {
        throw new SearchError('Empty parentheses in query.');
      }
      const inner = parseOr();
      if (!peek() || peek().type !== 'RPAREN') {
        throw new SearchError('Unbalanced parentheses in query.');
      }
      next();
      return inner;
    }
    if (tok.type === 'RPAREN') {
      throw new SearchError('Unbalanced parentheses in query.');
    }
    next();
    if (tok.type === 'WORD') return { op: 'WORD', value: tok.value };
    if (tok.type === 'PHRASE') return { op: 'PHRASE', value: tok.value };
    if (tok.type === 'TAG') return { op: 'TAG', value: tok.value };
    throw new SearchError('Unexpected token in query.');
  }

  const ast = parseOr();
  if (pos < tokens.length) {
    // Leftover tokens (e.g. an extra ')').
    throw new SearchError('Unbalanced parentheses in query.');
  }
  return ast;
}

export function parseQuery(input) {
  const trimmed = (input || '').trim();
  if (!trimmed) return null; // empty query matches everything
  const tokens = tokenize(trimmed);
  if (tokens.length === 0) return null;
  return parse(tokens);
}

// ---- Evaluator ---------------------------------------------------------
// bookmark: { title, url, description, note, tags: [names] }
export function evaluate(ast, bookmark) {
  if (!ast) return true;
  switch (ast.op) {
    case 'AND': return evaluate(ast.left, bookmark) && evaluate(ast.right, bookmark);
    case 'OR': return evaluate(ast.left, bookmark) || evaluate(ast.right, bookmark);
    case 'NOT': return !evaluate(ast.operand, bookmark);
    case 'WORD':
    case 'PHRASE':
      return matchText(ast.value, bookmark);
    case 'TAG':
      return matchTag(ast.value, bookmark);
    default:
      return false;
  }
}

function matchText(value, bm) {
  const needle = value.toLowerCase();
  const fields = [bm.title, bm.url, bm.description, bm.note];
  for (const f of fields) {
    if (f && f.toLowerCase().includes(needle)) return true;
  }
  // Word/phrase terms also match tag names (FR-009).
  for (const t of bm.tags || []) {
    if (t && t.toLowerCase().includes(needle)) return true;
  }
  return false;
}

function matchTag(value, bm) {
  const needle = value.toLowerCase();
  for (const t of bm.tags || []) {
    if (t && t.toLowerCase() === needle) return true;
  }
  return false;
}
// Shared list filtering used by GET /api/bookmarks and bulk selectAll (FR-017/FR-019).
import { allForView, sortBookmarks } from '../models/bookmark.js';
import { parseQuery, evaluate } from './search.js';

function toArray(v) {
  if (!v) return [];
  if (Array.isArray(v)) return v.flatMap((x) => String(x).split(','));
  return String(v).split(',');
}

// Returns filtered (and optionally sorted) bookmark list.
// opts: { q, view, include_tags, exclude_tags, sort }
// Throws SearchError on malformed q.
export function queryBookmarks(opts = {}) {
  const view = opts.view || 'normal';
  const ast = parseQuery(opts.q || '');           // may throw SearchError
  const include = toArray(opts.include_tags).map((t) => t.trim().toLowerCase()).filter(Boolean);
  const exclude = toArray(opts.exclude_tags).map((t) => t.trim().toLowerCase()).filter(Boolean);

  let list = allForView(view);
  list = list.filter((bm) => {
    const tagsLower = (bm.tags || []).map((t) => t.toLowerCase());
    if (include.length && !include.every((t) => tagsLower.includes(t))) return false;
    if (exclude.length && exclude.some((t) => tagsLower.includes(t))) return false;
    if (ast && !evaluate(ast, bm)) return false;
    return true;
  });

  if (opts.sort) list = sortBookmarks(list, opts.sort);
  return list;
}
// Best-effort page metadata capture (FR-003/FR-005).
// Plain fetch + cheerio first; Playwright/Chromium fallback for JS pages.
import * as cheerio from 'cheerio';

const FETCH_TIMEOUT = 12000;

async function fetchHtml(url) {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), FETCH_TIMEOUT);
  try {
    const res = await fetch(url, {
      redirect: 'follow',
      signal: ctrl.signal,
      headers: { 'user-agent': 'Mozilla/5.0 (BookmarkManager)' },
    });
    const contentType = res.headers.get('content-type') || '';
    const body = contentType.includes('text/html') ? await res.text() : '';
    return { html: body, contentType, finalUrl: res.url || url };
  } finally {
    clearTimeout(t);
  }
}

function extract($, baseUrl) {
  const abs = (u) => {
    if (!u) return null;
    try { return new URL(u, baseUrl).toString(); } catch { return null; }
  };
  const meta = (sel, attr = 'content') => {
    const el = $(sel).first();
    return el.length ? (el.attr(attr) || '').trim() : '';
  };

  const title =
    meta('meta[property="og:title"]') ||
    meta('meta[name="twitter:title"]') ||
    ($('title').first().text() || '').trim();

  const description =
    meta('meta[property="og:description"]') ||
    meta('meta[name="twitter:description"]') ||
    meta('meta[name="description"]');

  let preview =
    meta('meta[property="og:image"]') ||
    meta('meta[name="twitter:image"]');
  preview = abs(preview);

  // Favicon: rel icon variants, else default /favicon.ico
  let icon = '';
  $('link[rel]').each((_, el) => {
    const rel = ($(el).attr('rel') || '').toLowerCase();
    if (!icon && /(^|\s)(icon|shortcut icon|apple-touch-icon)(\s|$)/.test(rel)) {
      icon = $(el).attr('href') || '';
    }
  });
  icon = abs(icon) || abs('/favicon.ico');

  return { title, description, icon_url: icon, preview_image_url: preview };
}

async function fetchWithPlaywright(url) {
  const { chromium } = await import('playwright');
  const browser = await chromium.launch();
  try {
    const page = await browser.newPage();
    await page.goto(url, { waitUntil: 'domcontentloaded', timeout: FETCH_TIMEOUT });
    const html = await page.content();
    return html;
  } finally {
    await browser.close();
  }
}

// Returns { title, description, icon_url, preview_image_url } best-effort.
// Never throws; on total failure returns empty fields.
export async function fetchMetadata(url) {
  const empty = { title: '', description: '', icon_url: '', preview_image_url: '' };
  try {
    const { html, contentType } = await fetchHtml(url);
    if (contentType.includes('application/pdf')) return empty;
    if (html) {
      const $ = cheerio.load(html);
      const data = extract($, url);
      if (data.title || data.description) return data;
      // Fall through to Playwright if the static HTML gave nothing useful.
    }
    try {
      const rendered = await fetchWithPlaywright(url);
      if (rendered) return extract(cheerio.load(rendered), url);
    } catch { /* ignore rendering failure */ }
    return empty;
  } catch {
    return empty;
  }
}
// Preserved page copies (FR-021) + shared cleanup helper (T052).
// HTML pages -> self-contained single HTML file with inlined resources.
// PDF URLs  -> stored as-is.
import fs from 'node:fs';
import path from 'node:path';
import * as cheerio from 'cheerio';
import { PAGECOPY_DIR } from '../db/index.js';

const FETCH_TIMEOUT = 20000;
const MAX_ASSET_BYTES = 5 * 1024 * 1024;

async function fetchBuffer(url) {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), FETCH_TIMEOUT);
  try {
    const res = await fetch(url, {
      redirect: 'follow',
      signal: ctrl.signal,
      headers: { 'user-agent': 'Mozilla/5.0 (BookmarkManager)' },
    });
    const contentType = res.headers.get('content-type') || '';
    const buf = Buffer.from(await res.arrayBuffer());
    return { buf, contentType, finalUrl: res.url || url };
  } finally {
    clearTimeout(t);
  }
}

async function toDataUri(assetUrl) {
  try {
    const { buf, contentType } = await fetchBuffer(assetUrl);
    if (buf.length > MAX_ASSET_BYTES) return null;
    const mime = (contentType.split(';')[0] || 'application/octet-stream').trim();
    return `data:${mime};base64,${buf.toString('base64')}`;
  } catch {
    return null;
  }
}

async function buildSelfContainedHtml(html, baseUrl) {
  const $ = cheerio.load(html);
  const abs = (u) => { try { return new URL(u, baseUrl).toString(); } catch { return null; } };

  // Inline stylesheets.
  const links = $('link[rel="stylesheet"]').toArray();
  for (const el of links) {
    const href = abs($(el).attr('href'));
    if (!href) continue;
    try {
      const { buf } = await fetchBuffer(href);
      $(el).replaceWith(`<style>${buf.toString('utf8')}</style>`);
    } catch { /* drop broken stylesheet */ }
  }

  // Inline images as data URIs.
  const imgs = $('img[src]').toArray();
  for (const el of imgs) {
    const src = abs($(el).attr('src'));
    if (!src) continue;
    const dataUri = await toDataUri(src);
    if (dataUri) $(el).attr('src', dataUri);
  }

  // Remove scripts (offline-readable, not interactive) per approved scope.
  $('script').remove();

  // Add a <base> so any remaining relative links resolve.
  if ($('base').length === 0) $('head').prepend(`<base href="${baseUrl}">`);

  return $.html();
}

// Create a preserved copy; returns { path, kind }. Throws on failure so the
// route can report it without mutating the bookmark.
export async function createPageCopy(bookmarkId, url) {
  const { buf, contentType, finalUrl } = await fetchBuffer(url);
  const isPdf = contentType.includes('application/pdf') ||
    url.toLowerCase().split('?')[0].endsWith('.pdf');

  fs.mkdirSync(PAGECOPY_DIR, { recursive: true });

  if (isPdf) {
    const filePath = path.join(PAGECOPY_DIR, `${bookmarkId}.pdf`);
    fs.writeFileSync(filePath, buf);
    return { path: filePath, kind: 'pdf' };
  }

  const html = buf.toString('utf8');
  const selfContained = await buildSelfContainedHtml(html, finalUrl);
  const filePath = path.join(PAGECOPY_DIR, `${bookmarkId}.html`);
  fs.writeFileSync(filePath, selfContained, 'utf8');
  return { path: filePath, kind: 'html' };
}

// Shared cleanup helper used by single and bulk delete (T052/T038).
export function deletePageCopyFile(pageCopyPath) {
  if (!pageCopyPath) return;
  try {
    if (fs.existsSync(pageCopyPath)) fs.unlinkSync(pageCopyPath);
  } catch { /* best-effort */ }
}
// Internet Archive "Save Page Now" submission (FR-022).
// Best-effort external call; throws on failure so the route reports it
// without harming the bookmark.
const TIMEOUT = 20000;

export async function submitToArchive(url) {
  const saveUrl = 'https://web.archive.org/save/' + url;
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), TIMEOUT);
  try {
    const res = await fetch(saveUrl, {
      method: 'GET',
      redirect: 'follow',
      signal: ctrl.signal,
      headers: { 'user-agent': 'Mozilla/5.0 (BookmarkManager)' },
    });
    // Prefer the content-location header if present, else the final URL,
    // else construct the canonical snapshot URL.
    const contentLocation = res.headers.get('content-location');
    if (contentLocation) return 'https://web.archive.org' + contentLocation;
    if (res.url && res.url.includes('/web/')) return res.url;
    return 'https://web.archive.org/web/*/' + url;
  } finally {
    clearTimeout(t);
  }
}
// Markdown notes: render + sanitize (FR-006).
import { marked } from 'marked';
import createDOMPurify from 'dompurify';
import { JSDOM } from 'jsdom';

const window = new JSDOM('').window;
const DOMPurify = createDOMPurify(window);

marked.setOptions({ breaks: true, gfm: true });

export function renderNote(md) {
  if (!md) return '';
  const rawHtml = marked.parse(md);
  return DOMPurify.sanitize(rawHtml, {
    ALLOWED_TAGS: [
      'p', 'br', 'strong', 'em', 'del', 'code', 'pre', 'blockquote',
      'ul', 'ol', 'li', 'a', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'hr',
      'table', 'thead', 'tbody', 'tr', 'th', 'td',
    ],
    ALLOWED_ATTR: ['href', 'title'],
  });
}
// URL validation + normalization (FR-002).

export function normalizeUrl(raw) {
  if (typeof raw !== 'string') return null;
  let s = raw.trim();
  if (!s) return null;
  // Add a scheme if missing so bare "example.com" is accepted.
  if (!/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\//.test(s)) {
    s = 'https://' + s;
  }
  let u;
  try {
    u = new URL(s);
  } catch {
    return null;
  }
  if (u.protocol !== 'http:' && u.protocol !== 'https:') return null;
  if (!u.hostname || !u.hostname.includes('.')) return null;
  // Drop a trailing slash on the path-only root for stable uniqueness.
  return u.toString();
}

export function isValidUrl(raw) {
  return normalizeUrl(raw) !== null;
}
import express from 'express';
import multer from 'multer';
import * as Bookmark from '../models/bookmark.js';
import { setBookmarkTags } from '../models/tag.js';
import db from '../db/index.js';
import { normalizeUrl } from '../services/url.js';
import { parseBookmarksHtml, generateBookmarksHtml } from '../services/porthtml.js';

const router = express.Router();
const upload = multer({ storage: multer.memoryStorage(), limits: { fileSize: 20 * 1024 * 1024 } });

// Import Netscape bookmark HTML; merge by URL (FR-020).
router.post('/import', upload.single('file'), (req, res) => {
  const html = req.file ? req.file.buffer.toString('utf8') : req.body.html;
  if (!html) return res.status(400).json({ error: 'No file provided.' });
  let items;
  try {
    items = parseBookmarksHtml(html);
  } catch (e) {
    return res.status(400).json({ error: e.message });
  }
  let imported = 0;
  let merged = 0;
  const setDates = db.prepare('UPDATE bookmarks SET created_at = ?, updated_at = ? WHERE id = ?');
  for (const it of items) {
    const url = normalizeUrl(it.url);
    if (!url) continue;
    const existing = Bookmark.getByUrl(url);
    if (existing) {
      // Merge: keep bookmark, union tags, keep earliest created date.
      const unionTags = Array.from(new Set([...(existing.tags || []), ...(it.tags || [])]));
      setBookmarkTags(existing.id, unionTags);
      merged++;
    } else {
      const created = Bookmark.create({ url, title: it.title, tags: it.tags });
      // Preserve original dates from the import file (SC-006).
      setDates.run(it.created_at, it.updated_at, created.id);
      imported++;
    }
  }
  res.json({ imported, merged });
});

// Export all bookmarks as Netscape bookmark HTML (FR-020).
router.get('/export', (req, res) => {
  const bookmarks = Bookmark.allBookmarksForExport();
  const html = generateBookmarksHtml(bookmarks);
  res.setHeader('Content-Type', 'text/html; charset=utf-8');
  res.setHeader('Content-Disposition', 'attachment; filename="bookmarks.html"');
  res.send(html);
});

