  filters.forEach((f) => {
    const c = el('span', { className: 'chip saved-filter', title: 'Apply saved filter' }, '★ ' + f.name);
    c.onclick = () => applyFilter(f);
    const x = el('button', { title: 'Delete filter', onclick: async (e) => {
