// Shared app state + list loading. Components import this and call reload().
import { api } from './api.js';

export const state = {
  view: 'normal',
  q: '',
  sort: '',            // '' => use preference default (server decides)
  includeTags: [],
  excludeTags: [],
  page: 1,
  items: [],
  total: 0,
  selection: new Set(),
  prefs: { default_sort: 'newest', page_size: 25, text_size: 'medium' },
};

const listeners = [];
export function onChange(fn) { listeners.push(fn); }
function emit() { listeners.forEach((fn) => fn()); }

export function currentQueryParams() {
  const p = new URLSearchParams();
  if (state.q) p.set('q', state.q);
  p.set('view', state.view);
  if (state.sort) p.set('sort', state.sort);
  state.includeTags.forEach((t) => p.append('include_tags', t));
  state.excludeTags.forEach((t) => p.append('exclude_tags', t));
  p.set('page', String(state.page));
  return p;
}

// selectAll payload mirrors the current filter so bulk affects the same set.
export function selectAllPayload() {
  return {
    q: state.q,
    view: state.view,
    include_tags: state.includeTags,
    exclude_tags: state.excludeTags,
  };
}

let lastError = '';
export function getError() { return lastError; }

export async function reload() {
  try {
    const data = await api.get('/api/bookmarks?' + currentQueryParams().toString());
    state.items = data.items;
    state.total = data.total;
    // Drop selections no longer visible.
    const visible = new Set(data.items.map((b) => b.id));
    state.selection = new Set([...state.selection].filter((id) => visible.has(id)));
    lastError = '';
  } catch (e) {
    state.items = [];
    state.total = 0;
    lastError = e.message;
  }
  emit();
}
// Tag input widget with type-ahead suggestions (FR-014/FR-014a).
import { api } from './api.js';

// Creates a tag input bound to an array of tag names. Returns { element, getTags }.
export function createTagInput(initial = []) {
  const tags = [...initial];
  const wrap = document.createElement('div');
  wrap.className = 'tag-input-wrap';

  const chips = document.createElement('div');
  chips.className = 'tags';
  const input = document.createElement('input');
  input.type = 'text';
  input.placeholder = 'Add tag…';
  input.autocomplete = 'off';
  const sugg = document.createElement('div');
  sugg.className = 'suggestions';
  sugg.hidden = true;

  wrap.append(chips, input, sugg);

  function renderChips() {
    chips.innerHTML = '';
    tags.forEach((t, i) => {
      const chip = document.createElement('span');
      chip.className = 'chip';
      chip.textContent = t;
      const x = document.createElement('button');
      x.type = 'button';
      x.textContent = '×';
      x.onclick = () => { tags.splice(i, 1); renderChips(); };
      chip.append(x);
      chips.append(chip);
    });
  }

  function addTag(name) {
    const clean = name.trim();
    if (!clean) return;
    // Reuse existing (case-insensitive) name; never duplicate (FR-014a).
    if (!tags.some((t) => t.toLowerCase() === clean.toLowerCase())) tags.push(clean);
    input.value = '';
    sugg.hidden = true;
    renderChips();
  }

  let activeIdx = -1;
  async function showSuggestions() {
    const q = input.value.trim();
    if (!q) { sugg.hidden = true; return; }
    const { tags: matches } = await api.get('/api/tags?q=' + encodeURIComponent(q));
    const filtered = matches.filter((m) => !tags.some((t) => t.toLowerCase() === m.toLowerCase()));
    if (filtered.length === 0) { sugg.hidden = true; return; }
    sugg.innerHTML = '';
    activeIdx = -1;
    filtered.slice(0, 8).forEach((m) => {
      const d = document.createElement('div');
      d.textContent = m;
      d.onmousedown = (e) => { e.preventDefault(); addTag(m); };
      sugg.append(d);
    });
    sugg.hidden = false;
  }

  input.addEventListener('input', showSuggestions);
  input.addEventListener('keydown', (e) => {
    const opts = [...sugg.querySelectorAll('div')];
    if (e.key === 'Enter') {
      e.preventDefault();
      if (activeIdx >= 0 && opts[activeIdx]) addTag(opts[activeIdx].textContent);
      else addTag(input.value);
    } else if (e.key === 'ArrowDown' && opts.length) {
      e.preventDefault(); activeIdx = (activeIdx + 1) % opts.length;
      opts.forEach((o, i) => o.classList.toggle('active', i === activeIdx));
    } else if (e.key === 'ArrowUp' && opts.length) {
      e.preventDefault(); activeIdx = (activeIdx - 1 + opts.length) % opts.length;
      opts.forEach((o, i) => o.classList.toggle('active', i === activeIdx));
    } else if (e.key === 'Escape') {
      sugg.hidden = true;
    } else if ((e.key === ',' )) {
      e.preventDefault(); addTag(input.value);
    }
  });
  input.addEventListener('blur', () => { setTimeout(() => (sugg.hidden = true), 150); });

  renderChips();
  return { element: wrap, getTags: () => [...tags] };
}
// Small modal + message helpers.
const backdrop = () => document.getElementById('modal-backdrop');
const modalEl = () => document.getElementById('modal');

export function openModal(node) {
  const m = modalEl();
  m.innerHTML = '';
  m.append(node);
  backdrop().hidden = false;
}
export function closeModal() {
  backdrop().hidden = true;
  modalEl().innerHTML = '';
}
document.addEventListener('click', (e) => {
  if (e.target === backdrop()) closeModal();
});

export function showMessage(text, isError = false) {
  const el = document.getElementById('message');
  el.textContent = text;
  el.className = 'message' + (isError ? ' error' : '');
  el.hidden = false;
  clearTimeout(el._t);
  el._t = setTimeout(() => { el.hidden = true; }, 5000);
}

export function el(tag, props = {}, children = []) {
  const node = document.createElement(tag);
  Object.assign(node, props);
  for (const c of [].concat(children)) {
    if (c == null) continue;
    node.append(c.nodeType ? c : document.createTextNode(c));
  }
  return node;
}
:root {
  --fs: 16px;
  --bg: #f5f6f8;
  --card: #ffffff;
  --border: #e2e5ea;
  --text: #1e2430;
  --muted: #6b7280;
  --accent: #2563eb;
  --danger: #dc2626;
}
body[data-text-size="small"] { --fs: 14px; }
body[data-text-size="medium"] { --fs: 16px; }
body[data-text-size="large"] { --fs: 18px; }

* { box-sizing: border-box; }
/* The `hidden` attribute must always win over display rules below,
   so dialogs/bars stay fully absent until deliberately shown. */
[hidden] { display: none !important; }
body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  font-size: var(--fs);
  color: var(--text);
  background: var(--bg);
}
.topbar {
  display: flex; align-items: center; gap: 16px;
  padding: 12px 20px; background: var(--card); border-bottom: 1px solid var(--border);
  position: sticky; top: 0; z-index: 10;
}
.topbar h1 { font-size: 1.2em; margin: 0; }
.views { display: flex; gap: 6px; margin-left: 8px; }
.view-tab {
  border: 1px solid var(--border); background: transparent; padding: 6px 14px;
  border-radius: 20px; cursor: pointer; font-size: 0.9em; color: var(--text);
}
.view-tab.active { background: var(--accent); color: #fff; border-color: var(--accent); }
#prefs-btn { margin-left: auto; }

.save-bar, .toolbar {
  display: flex; gap: 8px; padding: 12px 20px; align-items: center;
  background: var(--card); border-bottom: 1px solid var(--border);
}
.save-bar #new-url, .toolbar #search { flex: 1; }
input[type="text"], select, textarea {
  padding: 9px 12px; border: 1px solid var(--border); border-radius: 8px;
  font-size: 1em; font-family: inherit; background: #fff; color: var(--text);
}
button, .button {
  padding: 9px 14px; border: 1px solid var(--accent); background: var(--accent);
  color: #fff; border-radius: 8px; cursor: pointer; font-size: 0.95em;
  text-decoration: none; display: inline-block;
}
button.ghost, .button.ghost {
  background: transparent; color: var(--text); border-color: var(--border);
}
button.danger { background: var(--danger); border-color: var(--danger); }
button:disabled { opacity: 0.5; cursor: default; }

.filter-tags-bar, .saved-filters { padding: 0 20px; display: flex; gap: 8px; flex-wrap: wrap; }
.filter-tags-bar:not(:empty), .saved-filters:not(:empty) { padding-top: 10px; }
.chip {
  display: inline-flex; align-items: center; gap: 6px; padding: 3px 10px;
  border-radius: 14px; font-size: 0.82em; background: #eef2ff; color: var(--accent);
  border: 1px solid #dbe2ff;
}
.chip.exclude { background: #fef2f2; color: var(--danger); border-color: #fecaca; }
.chip button { all: unset; cursor: pointer; font-weight: bold; }
.saved-filter { cursor: pointer; }

.bulk-bar {
  position: sticky; top: 58px; z-index: 9;
  display: flex; gap: 8px; align-items: center; flex-wrap: wrap;
  margin: 10px 20px; padding: 10px 14px; background: #eef2ff;
  border: 1px solid #dbe2ff; border-radius: 10px;
}
.message {
  margin: 10px 20px; padding: 10px 14px; border-radius: 8px;
  background: #fef9c3; border: 1px solid #fde68a;
}
.message.error { background: #fef2f2; border-color: #fecaca; color: var(--danger); }

.list { padding: 16px 20px; display: flex; flex-direction: column; gap: 12px; }
.card {
  display: flex; gap: 12px; padding: 14px; background: var(--card);
  border: 1px solid var(--border); border-radius: 10px;
}
.card.selected { border-color: var(--accent); box-shadow: 0 0 0 1px var(--accent); }
.card .sel { align-self: flex-start; }
.card .icon { width: 20px; height: 20px; flex-shrink: 0; margin-top: 3px; border-radius: 4px; }
.card .body { flex: 1; min-width: 0; }
.card .title { font-weight: 600; }
.card .title a { color: var(--text); text-decoration: none; }
.card .title a:hover { color: var(--accent); }
.card .url { color: var(--muted); font-size: 0.82em; word-break: break-all; }
.card .desc { color: #374151; margin: 6px 0; font-size: 0.92em; }
.card .tags { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 6px; }
.card .badges { display: flex; gap: 6px; margin-top: 6px; }
.badge { font-size: 0.72em; padding: 2px 8px; border-radius: 10px; background: #f1f5f9; color: var(--muted); }
.badge.unread { background: #fef3c7; color: #92400e; }
.card .actions { display: flex; flex-direction: column; gap: 6px; align-items: flex-end; }
.card .actions button { padding: 5px 10px; font-size: 0.8em; }
.empty { text-align: center; color: var(--muted); padding: 60px 20px; }

.modal-backdrop {
  position: fixed; inset: 0; background: rgba(0,0,0,0.4);
  display: flex; align-items: center; justify-content: center; z-index: 100;
}
.modal {
  background: var(--card); border-radius: 12px; padding: 22px;
  width: min(560px, 92vw); max-height: 88vh; overflow: auto;
}
.modal h2 { margin-top: 0; }
.field { display: flex; flex-direction: column; gap: 5px; margin-bottom: 14px; }
.field label { font-size: 0.85em; color: var(--muted); }
.modal-actions { display: flex; gap: 8px; justify-content: flex-end; margin-top: 8px; }
.tag-input-wrap { position: relative; }
.suggestions {
  position: absolute; left: 0; right: 0; top: 100%; background: #fff;
  border: 1px solid var(--border); border-radius: 8px; z-index: 5; max-height: 180px; overflow: auto;
}
.suggestions div { padding: 8px 12px; cursor: pointer; }
.suggestions div:hover, .suggestions div.active { background: #eef2ff; }
.note-html { background: #f9fafb; padding: 10px 12px; border-radius: 8px; }
.note-html :first-child { margin-top: 0; }
.note-html :last-child { margin-bottom: 0; }
.row { display: flex; gap: 8px; align-items: center; }
